static int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}
// call: fact(4)

static int f(int n) {
    if (n == 0) return 0;
    return f(n - 1);
}
// call: f(3)

static int fib(int n) {
    if (n < 2) return n;
    return fib(n - 1) + fib(n - 2);
}
// call: fib(5)

static void change(int[] a) {
    a[0] = 100;
}
// in main:
int[] arr = {1, 2};
change(arr);
System.out.println(arr[0]);

static void reset(int[] a) {
    a = new int[]{9, 9};
}
// in main:
int[] arr = {1, 2};
reset(arr);
System.out.println(arr[0]);

static void go(int n) {
    if (n == 0) {
        System.out.println("done");
        return;
    }
    go(n - 1);
}
// call: go(2)

static int bad(int n) {
    return bad(n - 1);
}

static int sum(int n) {
    if (n == 1) return 1;
    return n + sum(n - 1);
}
// call: sum(4)

static void permute(String p, String rest) {
    if (rest.isEmpty()) { System.out.println(p); return; }
    for (int i = 0; i < rest.length(); i++) {
        permute(p + rest.charAt(i),
                rest.substring(0, i) + rest.substring(i + 1));
    }
}
// call: permute("", "ab")
